arguments.file_text:
@* Sidebar navigation for settings sections *@

<div class="nav flex-column nav-pills me-3" role="tablist" aria-orientation="vertical">
    @foreach (var tab in Tabs)
    {
        <button class="nav-link text-start @(tab == ActiveTab ? "active" : "")"
                @onclick="() => OnTabChanged.InvokeAsync(tab)">
            <span class="me-2">@GetIcon(tab)</span> @tab
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ActiveTab { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnTabChanged { get; set; }

    private static readonly string[] Tabs = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string tab) => tab switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => ""
    };
}

@* Profile editing section *@

<div class="card">
    <div class="card-header"><h5 class="mb-0">Profile Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="row mb-4">
            <div class="col-auto">
                <div class="border rounded p-2 text-center" style="width: 120px; height: 120px; overflow: hidden;">
                    <img src="@AvatarUrl" alt="Avatar" class="img-fluid rounded" style="max-height: 100%;" />
                </div>
                <small class="text-muted d-block mt-1 text-truncate" style="max-width: 120px;" title="@AvatarUrl">@AvatarUrl</small>
            </div>
            <div class="col">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="Email" />
                </div>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="Bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private bool IsSaving;
    private string? StatusMessage;

    protected override void OnParametersSet() => LoadFromProfile();

    private void LoadFromProfile()
    {
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
        StatusMessage = null;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Profile saved successfully!";
    }

    private void Discard() => LoadFromProfile();
}

@* Notification preferences section *@

<div class="card">
    <div class="card-header"><h5 class="mb-0">Notification Preferences</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <h6>General</h6>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6>Muted Channels</h6>
            <p class="text-muted small">Uncheck a channel to receive notifications from it.</p>
            @foreach (var channel in AllChannels)
            {
                var isMuted = MutedChannels.Contains(channel);
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        #@channel <span class="badge bg-secondary ms-1">@(isMuted ? "muted" : "active")</span>
                    </label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Preferences
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = [];
    private List<string> AllChannels = [];
    private bool IsSaving;
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        EmailNotifications = Prefs.EmailNotifications;
        PushNotifications = Prefs.PushNotifications;
        WeeklyDigest = Prefs.WeeklyDigest;
        MutedChannels = [.. Prefs.MutedChannels];
        AllChannels = [.. Prefs.MutedChannels];
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, [.. MutedChannels]);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Preferences saved successfully!";
    }
}

@* Expandable change-password panel *@

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor: pointer;" @onclick="() => IsExpanded = !IsExpanded">
        <h6 class="mb-0">Change Password</h6>
        <span>@(IsExpanded ? "▲" : "▼")</span>
    </div>
    @if (IsExpanded)
    {
        <div class="card-body">
            @if (ErrorMessage is not null)
            {
                <div class="alert alert-danger">@ErrorMessage</div>
            }
            @if (SuccessMessage is not null)
            {
                <div class="alert alert-success">@SuccessMessage</div>
            }

            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="CurrentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="NewPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="ConfirmPassword" />
            </div>
            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@IsSubmitting">
                @if (IsSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private bool IsSubmitting;
    private string? ErrorMessage;
    private string? SuccessMessage;

    private async Task UpdatePasswordAsync()
    {
        ErrorMessage = null;
        SuccessMessage = null;

        if (string.IsNullOrWhiteSpace(CurrentPassword) ||
            string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All password fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        IsSubmitting = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        IsSubmitting = false;
        SuccessMessage = "Password updated successfully!";
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }
}

@* Confirmation dialog before revoking a session *@

@if (Visible)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@Session?.Device</strong> from <strong>@Session?.Location</strong>?</p>
                    <p class="text-muted small">This will immediately sign out that device.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@* Table of active sessions with revoke capability *@

<div class="card mb-3">
    <div class="card-header"><h6 class="mb-0">Active Sessions</h6></div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatTime(session.LastActive)</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => OnRevokeRequested.InvokeAsync(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter, EditorRequired] public EventCallback<ActiveSession> OnRevokeRequested { get; set; }

    private static string FormatTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@* Security settings section — composes ChangePasswordPanel, ActiveSessionsTable, RevokeSessionDialog *@

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <div class="d-flex align-items-center justify-content-between">
                <div>
                    <h6 class="mb-0">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        @if (Security.TwoFactorEnabled)
                        {
                            <span class="text-success">● Enabled</span>
                        }
                        else
                        {
                            <span class="text-danger">● Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@TwoFactorEnabled"
                           @onchange="e => TwoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
            @if (Security.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                </small>
            }
        </div>
    </div>
</div>

<ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

<ActiveSessionsTable Sessions="@Security.Sessions.ToList()"
                     OnRevokeRequested="RequestRevoke" />

<RevokeSessionDialog Visible="@ShowRevokeDialog"
                     Session="@SessionToRevoke"
                     OnConfirm="ConfirmRevokeAsync"
                     OnCancel="CancelRevoke" />

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled;
    private bool ShowRevokeDialog;
    private ActiveSession? SessionToRevoke;
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        TwoFactorEnabled = Security.TwoFactorEnabled;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private void RequestRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            StatusMessage = $"Session on \"{SessionToRevoke.Device}\" has been revoked.";
        }
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }
}

@* Live preview of appearance settings *@

<div class="card mt-3">
    <div class="card-header"><h6 class="mb-0">Live Preview</h6></div>
    <div class="card-body @GetBgClass()" style="@GetPreviewStyle()">
        <h6 class="@GetTextClass()">Sample Heading</h6>
        <p class="@GetTextClass() mb-2">
            This is how your content will look with the selected appearance settings.
            The quick brown fox jumps over the lazy dog.
        </p>
        <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-3")">
            <button class="btn @GetBtnClass() btn-sm">Primary Button</button>
            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
        </div>
        <div class="@(CompactMode ? "small" : "")">
            <span class="badge bg-info me-1">Tag 1</span>
            <span class="badge bg-warning me-1">Tag 2</span>
            <span class="badge bg-success">Tag 3</span>
        </div>
        <p class="@GetTextClass() mt-2 mb-0 fst-italic small">
            Language: @Language | Compact: @(CompactMode ? "On" : "Off")
        </p>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "English";
    [Parameter] public bool CompactMode { get; set; }

    private string GetPreviewStyle()
    {
        var size = FontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = CompactMode ? "0.5rem" : "1rem";
        return $"font-size: {size}; padding: {padding}; border-radius: 0.375rem; transition: all 0.2s;";
    }

    private string GetBgClass() => Theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string GetTextClass() => Theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string GetBtnClass() => Theme switch
    {
        "Dark" => "btn-light",
        _ => "btn-primary"
    };
}

@* Appearance settings section *@

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(SelectedTheme == theme)"
                           @onchange="() => SelectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"size-{size}")" value="@size"
                           checked="@(SelectedFontSize == size)"
                           @onchange="() => SelectedFontSize = size" />
                    <label class="form-check-label" for="@($"size-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width: 250px;"
                    @bind="SelectedLanguage">
                @foreach (var lang in Languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       @bind="SelectedCompactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save
        </button>
    </div>
</div>

<AppearancePreview Theme="@SelectedTheme"
                   FontSize="@SelectedFontSize"
                   Language="@SelectedLanguage"
                   CompactMode="@SelectedCompactMode" />

@code {
    [Parameter, EditorRequired] public AppearanceSettings Appearance { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool SelectedCompactMode;
    private bool IsSaving;
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        SelectedTheme = Appearance.Theme;
        SelectedFontSize = Appearance.FontSize;
        SelectedLanguage = Appearance.Language;
        SelectedCompactMode = Appearance.CompactMode;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, SelectedCompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Appearance saved successfully!";
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h3 class="mb-4">⚙️ Settings</h3>

    @if (IsLoading)
    {
        <div class="d-flex justify-content-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-3 col-lg-2 mb-3">
                <SettingsSidebar ActiveTab="@ActiveTab" OnTabChanged="tab => ActiveTab = tab" />
            </div>
            <div class="col-md-9 col-lg-10">
                @switch (ActiveTab)
                {
                    case "Profile":
                        <ProfileSection Profile="@Profile!" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@NotifPrefs!" OnSave="SaveNotifPrefsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Security="@Security!"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevokeSession="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Appearance="@AppearanceConfig!" OnSave="SaveAppearanceAsync" />
