@* Sidebar navigation for settings sections *@

<div class="nav flex-column nav-pills me-3" role="tablist" aria-orientation="vertical">
    @foreach (var tab in Tabs)
    {
        <button class="nav-link text-start @(tab == ActiveTab ? "active" : "")"
                @onclick="() => OnTabChanged.InvokeAsync(tab)">
            <span class="me-2">@GetIcon(tab)</span> @tab
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ActiveTab { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnTabChanged { get; set; }

    private static readonly string[] Tabs = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string tab) => tab switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => ""
    };
}

@* Profile editing section *@

<div class="card">
    <div class="card-header"><h5 class="mb-0">Profile Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="row mb-4">
            <div class="col-auto">
                <div class="border rounded p-2 text-center" style="width: 120px; height: 120px; overflow: hidden;">
                    <img src="@AvatarUrl" alt="Avatar" class="img-fluid rounded" style="max-height: 100%;" />
                </div>
                <small class="text-muted d-block mt-1 text-truncate" style="max-width: 120px;" title="@AvatarUrl">@AvatarUrl</small>
            </div>
            <div class="col">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="Email" />
                </div>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="Bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private bool IsSaving;
    private string? StatusMessage;

    protected override void OnParametersSet() => LoadFromProfile();

    private void LoadFromProfile()
    {
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
        StatusMessage = null;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Profile saved successfully!";
    }

    private void Discard() => LoadFromProfile();
}

