@* Confirmation dialog before revoking a session *@

@if (Visible)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@Session?.Device</strong> from <strong>@Session?.Location</strong>?</p>
                    <p class="text-muted small">This will immediately sign out that device.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@* Table of active sessions with revoke capability *@

<div class="card mb-3">
    <div class="card-header"><h6 class="mb-0">Active Sessions</h6></div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatTime(session.LastActive)</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => OnRevokeRequested.InvokeAsync(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter, EditorRequired] public EventCallback<ActiveSession> OnRevokeRequested { get; set; }

    private static string FormatTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@* Security settings section — composes ChangePasswordPanel, ActiveSessionsTable, RevokeSessionDialog *@

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <div class="d-flex align-items-center justify-content-between">
                <div>
                    <h6 class="mb-0">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        @if (Security.TwoFactorEnabled)
                        {
                            <span class="text-success">● Enabled</span>
                        }
                        else
                        {
                            <span class="text-danger">● Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@TwoFactorEnabled"
                           @onchange="e => TwoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
            @if (Security.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                </small>
            }
        </div>
    </div>
</div>

<ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

<ActiveSessionsTable Sessions="@Security.Sessions.ToList()"
                     OnRevokeRequested="RequestRevoke" />

<RevokeSessionDialog Visible="@ShowRevokeDialog"
                     Session="@SessionToRevoke"
                     OnConfirm="ConfirmRevokeAsync"
                     OnCancel="CancelRevoke" />

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled;
    private bool ShowRevokeDialog;
    private ActiveSession? SessionToRevoke;
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        TwoFactorEnabled = Security.TwoFactorEnabled;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private void RequestRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            StatusMessage = $"Session on \"{SessionToRevoke.Device}\" has been revoked.";
        }
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }
}

