@* Live preview of appearance settings *@

<div class="card mt-3">
    <div class="card-header"><h6 class="mb-0">Live Preview</h6></div>
    <div class="card-body @GetBgClass()" style="@GetPreviewStyle()">
        <h6 class="@GetTextClass()">Sample Heading</h6>
        <p class="@GetTextClass() mb-2">
            This is how your content will look with the selected appearance settings.
            The quick brown fox jumps over the lazy dog.
        </p>
        <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-3")">
            <button class="btn @GetBtnClass() btn-sm">Primary Button</button>
            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
        </div>
        <div class="@(CompactMode ? "small" : "")">
            <span class="badge bg-info me-1">Tag 1</span>
            <span class="badge bg-warning me-1">Tag 2</span>
            <span class="badge bg-success">Tag 3</span>
        </div>
        <p class="@GetTextClass() mt-2 mb-0 fst-italic small">
            Language: @Language | Compact: @(CompactMode ? "On" : "Off")
        </p>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "English";
    [Parameter] public bool CompactMode { get; set; }

    private string GetPreviewStyle()
    {
        var size = FontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = CompactMode ? "0.5rem" : "1rem";
        return $"font-size: {size}; padding: {padding}; border-radius: 0.375rem; transition: all 0.2s;";
    }

    private string GetBgClass() => Theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string GetTextClass() => Theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string GetBtnClass() => Theme switch
    {
        "Dark" => "btn-light",
        _ => "btn-primary"
    };
}

@* Appearance settings section *@

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance Settings</h5></div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(SelectedTheme == theme)"
                           @onchange="() => SelectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"size-{size}")" value="@size"
                           checked="@(SelectedFontSize == size)"
                           @onchange="() => SelectedFontSize = size" />
                    <label class="form-check-label" for="@($"size-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width: 250px;"
                    @bind="SelectedLanguage">
                @foreach (var lang in Languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

