        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, SelectedCompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Appearance saved successfully!";
    }
}

